```python
def retry(times=3):
    def deco(fn):
        def wrapper(*a, **kw):
            for i in range(times):
                try:
                    print("attempt", i)
                    kw["idempotency_key"] = str(uuid.uuid4())
                    return fn(*a, **kw)
                except (Timeout, ServerError):
                    continue
            raise
        return wrapper
    return deco
